(v_topic_id, 'obligation', '/ˌɒblɪˈɡeɪʃn/', '(n) nghĩa vụ, bổn phận', 'Members of egalitarian tribal groups feel a profound ethical obligation to share harvested food with their entire community.', 'Test 4', 3, 81, NOW() + interval '9681 seconds'),
(v_topic_id, 'disparity', '/dɪˈspærəti/', '(n) sự chênh lệch, khác biệt lớn', 'Social structures in early nomadic bands featured mechanisms designed to prevent a severe disparity of status.', 'Test 4', 3, 82, NOW() + interval '9682 seconds'),
(v_topic_id, 'domineering', '/ˌdɒmɪˈnɪərɪŋ/', '(adj) hống hách, áp đảo', 'Social groups in prehistoric times often chose to ostracise members who became overly aggressive or domineering.', 'Test 4', 3, 83, NOW() + interval '9683 seconds'),
(v_topic_id, 'ostracise', '/ˈɒstrəsaɪz/', '(v) tẩy chay, cô lập', 'Social groups in prehistoric times often chose to ostracise members who became overly aggressive or domineering.', 'Test 4', 3, 84, NOW() + interval '9684 seconds'),
(v_topic_id, 'autonomy', '/ɔːˈtɒnəmi/', '(n) sự tự chủ, quyền tự quyết', 'Female foragers in primitive nomadic groups typically enjoyed a exceptionally high level of autonomy.', 'Test 4', 3, 85, NOW() + interval '9685 seconds'),
