(v_topic_id, 'ruthless', '/ˈruːθləs/', '(adj) tàn nhẫn, nhẫn tâm', 'Experiencing severe habitat loss can cause wild animal populations to adopt unnaturally ruthless behaviors.', 'Test 4', 3, 94, NOW() + interval '9694 seconds'),
(v_topic_id, 'impulse', '/ˈɪmpʌls/', '(n) sự thôi thúc, bốc đồng', 'The impulse to learn drove me to study night and day.', 'Test 4', 3, 95, NOW() + interval '9695 seconds'),
